#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
# list.sh: malformed date -> exit 2, message on stderr, nothing on stdout
bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
[ -z "$(bash src/list.sh 2026/01/01 2>/dev/null)" ] || { echo "bad date should print nothing on stdout"; fail=1; }
# list.sh: month and day must be in range
BOOKINGS=$t bash src/list.sh 2026-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "month 13 should exit 2"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-00 >/dev/null 2>&1; [ $? = 2 ] || { echo "day 00 should exit 2"; fail=1; }
# list.sh: a well-formed date still lists
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02 2>&1)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "valid date should list"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-02 >/dev/null 2>&1; [ $? = 0 ] || { echo "valid date should exit 0"; fail=1; }
# remind.sh: the same check, before it calls list.sh
bash src/remind.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: malformed date should exit 2"; fail=1; }
[ "$(bash src/remind.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "remind: bad date message"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02 2>&1)" = 'reminder to x: aoi 2026-01-02 10:00-11:00' ] || { echo "remind: valid date should remind"; fail=1; }
rm -f "$t"; exit $fail

